function catIssues(s){const g=s.groups.find(x=>x.label==='Shop by Category'),a=[];if(!g)return['missing category'];if(g.choices.length!==9)a.push(`category count ${g.choices.length}`);EXPECT.forEach(([lab,h],i)=>{const c=g.choices[i];if(!c)a.push(`missing ${lab}`);else{if(c.label!==lab)a.push(`wrong label ${c.label}`);if(!c.target.startsWith(`/collections/${h}?`))a.push(`${lab} bad target ${c.target}`);try{if(new URL(c.target,BASE).searchParams.get('sq_root')!=='accessories-gifts-collectibles')a.push(`${lab} missing sq_root`)}catch{a.push(`${lab} invalid target`)}}});if(g.choices.some(c=>/\/collections\/all(?:\?|$)/.test(c.target)))a.push('/collections/all target');return a}
function baseIssues(s,mobile){const a=[];if(s.ready!=='true'||s.error)a.push(`V3 ${s.error||s.ready}`);if(!s.sidebar)a.push('sidebar missing');if(s.header?.text!=='REFINE PRODUCTS')a.push('header text');if(s.header?.bg!=='rgb(8, 40, 63)'||s.header?.fg!=='rgb(255, 255, 255)')a.push('header colors');if((s.header?.rightGap??99)>1.5)a.push(`header gap ${s.header?.rightGap}`);if(s.overflow)a.push('horizontal overflow');const vg=s.grids.filter(g=>g.visible);if(vg.length!==1)a.push(`visible grids ${vg.length}`);if(!vg[0]?.inV3)a.push('non-V3 grid visible');if(!s.cards)a.push('no products');if(mobile){if(s.sidebar?.position==='sticky')a.push('mobile sticky');if(s.cards&&s.firstRow!==2)a.push(`mobile columns ${s.firstRow}`)}else{if(s.sidebar?.position!=='sticky')a.push(`desktop sidebar ${s.sidebar?.position}`);if(s.cards&&s.firstRow!==3)a.push(`desktop columns ${s.firstRow}`);if(s.cardWidth<250)a.push(`card width ${s.cardWidth}`)}if(s.pageSizes.map(x=>x.value).join(',')!=='50,100,250')a.push('page sizes');s.pageSizes.forEach(x=>{if(!x.visible||x.label!==x.value)a.push(`hidden page-size ${x.value}`)});return a}
async function sweep(p,prefix,mobile){const points=[],issues=[];for(const [n,f] of [['top',0],['quarter',.25],['middle',.5],['three-quarter',.75],['bottom',1]]){await goFrac(p,f);const s=await state(p);points.push({name:n,...s});await snap(p,`${prefix}-${n}.png`);const vg=s.grids.filter(g=>g.visible);if(vg.length!==1||!vg[0]?.inV3)issues.push(`${n}: visible grids ${vg.length}, authoritative=${!!vg[0]?.inV3}`);const auth=s.grids.find(g=>g.inV3);const authInView=auth&&auth.rect.y<s.scroll.clientHeight&&auth.rect.y+auth.rect.h>0;if(!mobile&&authInView&&!s.sidebar?.viewport)issues.push(`${n}: sidebar absent while V3 grid in viewport`)}await reset(p);return{points,issues}}
