async function childTest(ctx){const p=await newPreviewPage(ctx);const r={pass:true};try{const det=p.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').filter({has:p.locator(':scope>summary',{hasText:'Shop by Category'})}).first();if(await det.getAttribute('open')===null)await det.locator(':scope>summary').click();await det.locator('input').first().click({force:true,noWaitAfter:true});await p.waitForURL(/challenge-coins-display-holders/,{timeout:20000});await ready(p);const s=await state(p);r.url=p.url();r.issues=catIssues(s);r.pass=r.url.includes('/collections/challenge-coins-display-holders')&&!r.issues.length}catch(e){r.pass=false;r.error=String(e);r.url=p.url()}finally{await p.close()}return r}
async function pageSizeTests(ctx){const out=[];for(const n of [50,100,250]){const p=await ctx.newPage();try{const u=new URL(startUrl());u.searchParams.set('sq_per_page',n);u.searchParams.set('sq_view_page','1');await p.goto(u.toString(),{waitUntil:'domcontentloaded',timeout:90000});await ready(p);const s=await state(p),checked=s.pageSizes.find(x=>x.value===String(n))?.checked===true,labels=s.pageSizes.every(x=>x.visible&&x.label===x.value);out.push({size:n,cards:s.cards,checked,labels,pass:s.cards>0&&s.cards<=n&&checked&&labels})}catch(e){out.push({size:n,pass:false,error:String(e)})}finally{await p.close()}}return out}

